// Build scripts run at build time, not runtime. Panics here fail
// `cargo build`, which is the intended behaviour for missing files
// or invalid embedded data.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::env;
use std::path::Path;

/// Vendored generated lexer (committed to repo, regenerated by re2rust on macOS).
const VENDORED_LEXER: &str = "src/generated/lexer.rs";

/// Generated Rust file name in OUT_DIR.
const LEXER_RUST_FILE: &str = "lexer.rs";

fn main() -> Result<(), Box<dyn std::error::Error>> {
    println!("cargo:rerun-if-changed=src");
    let root = std::path::PathBuf::from(
        std::env::var_os("CARGO_MANIFEST_DIR").ok_or("missing CARGO_MANIFEST_DIR")?,
    );
    let fingerprint = talkbank_build::SourceFingerprint::read_tree(&root.join("src"))?;
    println!("cargo:rustc-env=TALKBANK_PARSER_SOURCE_FINGERPRINT={fingerprint}");

    let out_dir = env::var("OUT_DIR").expect("OUT_DIR not set by Cargo");
    let out_path = Path::new(&out_dir).join(LEXER_RUST_FILE);

    // Copy the vendored (pre-generated) lexer to OUT_DIR.
    //
    // To regenerate, install the exact re2c-version.toml version and run:
    //   re2rust --no-unsafe -W -Wno-nondeterministic-tags --input-encoding utf8 --utf8 \
    //     --no-generation-date \
    //     --conditions -o src/generated/lexer.rs src/lexer.re
    //
    // `--no-generation-date` is REQUIRED so that regenerating produces a
    // byte-identical file, which is what makes a diff meaningful. Omitting it
    // embeds a timestamp header (`/* Generated by re2rust 4.5.1 on Wed ... */`)
    // and every regeneration then looks like a change.
    //
    // `just verify-vendored-lexer` checks the exact pinned generator version
    // and byte-compares regenerated output with the vendored source. Run it
    // after changing lexer.re or its generated includes. The local publication
    // gate also invokes it. This build script only copies the committed lexer;
    // an ordinary Cargo build does not establish generator currency.
    //
    // See lexer.re header comment for why -Wno-nondeterministic-tags is needed.
    std::fs::copy(VENDORED_LEXER, &out_path)?;

    Ok(())
}
